import XCTest
#if canImport(Passport)
@testable import Passport
#else
@testable import PassportCore
#endif
final class CoreTests:XCTestCase {
    func visit()->Entry{var r=Entry.new(visit:true);r["name"]="Example Cafe";r["suburb"]="Centre";r["date"]="2026-11-01";r.fields["total"] = .number(Decimal(string:"30.25")!);r.fields["people"] = .number(2);r.fields["rating"] = .number(4);return r}
    func sample()->PassportArchive{var a=PassportArchive();a.set("visits",[visit()]);var w=Entry.new(visit:false);w["name"]="Example Bistro";a.set("wants",[w]);return a}
    func testBrowserBackupRoundTripPreservesPhotosUnknownFieldsAndAmounts()throws{var a=sample();a.root["future"] = .object(["value":.number(123)]);var v=a.entries("visits");v[0]["photo"]="data:image/jpeg;base64,"+Data("photo-fixture".utf8).base64EncodedString();v[0]["custom"]="KEEP";a.set("visits",v);let b=try PassportArchive.decode(a.encoded());XCTAssertEqual(a,b);XCTAssertEqual(b.entries("visits")[0].total,Decimal(string:"30.25"));XCTAssertEqual(b.entries("visits")[0].photoData,Data("photo-fixture".utf8))}
    func testPlainArrayAndLegacyStateAreSupported()throws{let a=sample();let visits=try JSONEncoder().encode(JSONValue.array(a.root.list("visits")));XCTAssertEqual(try PassportArchive.decode(visits).entries("visits").count,1);var raw=a.root;raw.removeValue(forKey:"app");raw.removeValue(forKey:"version");XCTAssertEqual(try PassportArchive.decode(JSONEncoder().encode(JSONValue.object(raw))).entries("wants").count,1)}
    func testUnknownAppFutureVersionAndInvalidStructuresRejected(){for raw in [#"{}"#,#"{"app":"wrong","visits":[]}"#,#"{"version":2,"visits":[]}"#,#"{"visits":{}}"#]{XCTAssertThrowsError(try PassportArchive.decode(Data(raw.utf8)))}}
    func testDuplicateIDsAndBadRecordsRejected(){var a=sample();a.set("visits",[visit(),visit()]);var records=a.entries("visits");records[1].fields["id"]=records[0].fields["id"];a.set("visits",records);XCTAssertThrowsError(try a.validate());records[0]["name"]=" ";XCTAssertThrowsError(try PassportArchive.validate(records[0],type:"visits"))}
    func testInvalidDatesAndLeapDays(){XCTAssertNil(CivilDay.date("2026-02-29"));XCTAssertNil(CivilDay.date("2026-11-31"));XCTAssertNotNil(CivilDay.date("2028-02-29"));XCTAssertNil(CivilDay.date("2026-1-1"))}
    func testInvalidCostsRatingsPeopleAndPhotosRejected(){for (field,value) in [("total",JSONValue.number(-1)),("rating",.number(6)),("rating",.number(Decimal(string:"2.5")!)),("people",.number(0)),("people",.number(Decimal(string:"1.5")!)),("photo",.string("data:image/svg+xml;base64,AAAA")),("photo",.string("data:image/jpeg;base64,not-base64"))]{var r=visit();r.fields[field]=value;XCTAssertThrowsError(try PassportArchive.validate(r,type:"visits"))}}
    func testMergeKeepsExistingIDsAndAddsNewRecordsAndMetadata()throws{let original=sample();var incoming=original;var visits=incoming.entries("visits");visits[0]["name"]="Conflict";var extra=visit();extra["name"]="New cafe";visits.append(extra);incoming.set("visits",visits);incoming.root["newMetadata"] = .string("Keep");let(merged,count)=try original.merging(incoming);XCTAssertEqual(count,1);XCTAssertEqual(merged.entries("visits")[0]["name"],"Example Cafe");XCTAssertEqual(merged.root.text("newMetadata"),"Keep");XCTAssertEqual(merged.entries("wants"),original.entries("wants"))}
    func testStatsUseRatedVisitsOnlyAndRespectSuburbsAndCostPerPerson(){var a=sample();var next=visit();next["suburb"]="Other suburb";next.fields["rating"] = .number(0);a.set("visits",a.entries("visits")+[next]);XCTAssertEqual(a.uniqueRestaurants,2);XCTAssertEqual(a.averageRating,4);XCTAssertEqual(a.totalSpent,Decimal(string:"60.50"));XCTAssertEqual(next.perPerson,Decimal(string:"15.125"))}
    func testDecimalTotalsAreExact(){var a=sample();var first=visit(),second=visit();first.fields["total"] = .number(Decimal(string:"0.1")!);second.fields["total"] = .number(Decimal(string:"0.2")!);a.set("visits",[first,second]);XCTAssertEqual(a.totalSpent,Decimal(string:"0.3"))}
    func testCSVQuotesLineBreaksAndNeutralisesFormulas(){var a=sample();var v=a.entries("visits");v[0]["name"]=" =SUM(A1)";v[0]["notes"]="A \"quote\", and\nnew line";a.set("visits",v);let csv=a.csv();XCTAssertTrue(csv.contains("' =SUM(A1)"));XCTAssertTrue(csv.contains("A \"\"quote\"\", and\nnew line"));XCTAssertTrue(csv.hasPrefix("\u{FEFF}"))}
    func testCoordinatesAreRoundedAndInvalidPointsRejected(){let p=SearchPoint(lat:-34.92856,lon:138.6007);XCTAssertEqual(p.rounded,.init(lat:-34.929,lon:138.601));XCTAssertFalse(SearchPoint(lat:.nan,lon:0).valid);XCTAssertFalse(SearchPoint(lat:0,lon:181).valid)}
    func testPopularityRemainsASeparateSignalWithUnknownRatingAndSafeLinks()throws{let p=try PopularPlace(["id":.string("x"),"name":.string("Example"),"url":.string("javascript:bad"),"rating":.number(8)]);XCTAssertNil(p.rating);XCTAssertNil(p.reviews);XCTAssertNil(p.url);XCTAssertThrowsError(try PopularPlace([:]));XCTAssertNil(SafeLink.google("https://evil.example/"));XCTAssertNil(SafeLink.web("https://user:secret@example.com/"));XCTAssertNotNil(SafeLink.google("https://maps.google.com/?cid=1"))}
}
